const text = ($input.first().json.body.text || '04 test').trim();
const parts = text.split(/\s+/);

const feature = parts[0] || '04';
const env = parts[1] || 'test';
const user = $input.first().json.body.user_name || 'slack-user';

return {
  json: {
    feature,
    env,
    triggeredBy: `@${user}`
  }
};

const res = $input.first().json;
const isPass = res.success;

let responseText = '';
if (isPass) {
  responseText = `✅ *Execution PASSED* for Feature *${res.feature}* (${res.environment.toUpperCase()})\n• Passed: ${res.metrics.passed}/${res.metrics.totalScenarios} (100%)\n• Duration: ${res.durationSeconds}s\n• CBS Accounts: ${res.cbsAccountsCreated.join(', ') || 'None'}\n• Excel: http://localhost:5050/api/reports/download/excel`;
} else {
  const triage = res.aiTriage || {};
  responseText = `🚨 *Execution FAILED* for Feature *${res.feature}* (${res.environment.toUpperCase()})\n• Failed: ${res.metrics.failed}/${res.metrics.totalScenarios}\n• AI Root Cause: ${triage.rootCauseSummary || 'Assertion failed.'}\n• Recommended Fix: ${triage.recommendedAction || 'Check logs'}\n• Excel: http://localhost:5050/api/reports/download/excel`;
}

return {
  json: {
    response_type: "in_channel",
    text: responseText
  }
};
